const videos = items.map((item) => item.json).filter((video) => video && !video.error);

if (videos.length === 0) {
  throw new Error('No valid TikTok videos were returned by the scraper API.');
}

const rankedVideos = videos
  .map((video) => {
    const views = Number(video.playCount || 0);
    const likes = Number(video.diggCount || 0);
    const comments = Number(video.commentCount || 0);
    const shares = Number(video.shareCount || 0);
    const saves = Number(video.collectCount || 0);
    const engagement = likes + comments * 2 + shares * 3 + saves * 2;
    const engagementRate = views > 0 ? engagement / views : 0;

    return {
      ...video,
      engagementScore: engagement,
      engagementRate: Number(engagementRate.toFixed(4)),
    };
  })
  .filter((video) => video.author && video.author !== 'Unknown')
  .sort((a, b) => b.engagementRate - a.engagementRate);

const topVideos = rankedVideos.slice(0, 5);

const trendContext = topVideos
  .map((video, index) => [
    'Video ' + (index + 1),
    'Author: ' + video.author,
    'Views: ' + video.playCount,
    'Likes: ' + video.diggCount,
    'Comments: ' + video.commentCount,
    'Shares: ' + video.shareCount,
    'Saves: ' + video.collectCount,
    'Engagement rate: ' + video.engagementRate,
    'Description: ' + (video.description_full || 'No description'),
    'Hashtags: ' + (Array.isArray(video.hashtags) ? video.hashtags.join(', ') : ''),
    'Link: ' + video.video_link,
  ].join('\n'))
  .join('\n---\n');

const prompt = [
  'You are a short-form content strategist.',
  'Analyze these TikTok videos and create one original video idea inspired by the strongest pattern.',
  'Do not copy creators, captions, or copyrighted concepts.',
  '',
  'Return only valid JSON with these keys:',
  '- trend_summary',
  '- winning_pattern',
  '- original_hook',
  '- video_script',
  '- caption',
  '- suggested_hashtags',
  '- production_notes',
  '',
  'Scraped trend data:',
  trendContext,
].join('\n');

return [{ json: { prompt_text: prompt, top_videos: topVideos } }];
